export HOST="${HOST:-::}" PORT="${PORT:-8080}" EXTRACT_WORKER_PORT="${EXTRACT_WORKER_PORT:-3004}" WORKER_PORT="${WORKER_PORT:-3005}" ENV="${ENV:-local}" USE_DB_AUTHENTICATION=false POSTGRES_USER="${POSTGRES_USER:-postgres}" POSTGRES_DB="${POSTGRES_DB:-postgres}" POSTGRES_PORT="${POSTGRES_PORT:-5432}" NUM_WORKERS_PER_QUEUE="${NUM_WORKERS_PER_QUEUE:-8}" CRAWL_CONCURRENT_REQUESTS="${CRAWL_CONCURRENT_REQUESTS:-10}" MAX_CONCURRENT_JOBS="${MAX_CONCURRENT_JOBS:-5}" BROWSER_POOL_SIZE="${BROWSER_POOL_SIZE:-5}" HARNESS_STARTUP_TIMEOUT_MS="${HARNESS_STARTUP_TIMEOUT_MS:-60000}" LOGGING_LEVEL="${LOGGING_LEVEL:-INFO}"; node -e 'const net=require("net"),u=require("url");const t=Date.now();const w=(h,p)=>new Promise((ok,no)=>{const f=()=>{const s=net.connect({host:h,port:+p});s.on("connect",()=>{s.end();console.log("ready "+h+":"+p);ok()});s.on("error",()=>{s.destroy();if(Date.now()-t>300000)no(new Error("timeout "+h));else setTimeout(f,2000)})};f()});const m=new u.URL(process.env.NUQ_RABBITMQ_URL||"amqp://x:5672");Promise.all([w(process.env.POSTGRES_HOST,process.env.POSTGRES_PORT),w(m.hostname.replace(/^\[|\]$/g,""),m.port||5672)]).then(()=>process.exit(0),e=>{console.error(e.message);process.exit(1)})' && exec docker-entrypoint.sh node dist/src/harness.js --start-docker
